import {INFO_GENRES,MOODS,TRADE_METHODS,FILTER_FIELDS,FILTER_LABELS,INFO_FIELDS,normalizeInfo,normalizeState,normalizeFilter,hasFilter,filterDescription,matchesFilters,matchedReasons} from './book-info.js?v=20261030-ai1';

export function bookAISection(){return `<section class="book-ai" aria-labelledby="book-ai-heading"><h2 id="book-ai-heading">표지로 도서 정보 찾기</h2><p>사진에서 제목·저자를 읽고 실제 도서 정보를 검색해요. 사진은 AI 서비스로 전송되며, 책 상태와 교환 조건은 직접 확인해야 해요.</p><button type="button" class="secondary ai-fill" id="ai-fill-book">✦ AI로 책 정보 채우기</button><small id="book-ai-photo-help">첨부한 표지 사진이 있을 때 사용할 수 있어요.</small><div class="book-lookup"><label for="book-lookup-query">제목·ISBN으로 직접 검색</label><div><input id="book-lookup-query" maxlength="120" placeholder="인식이 어렵다면 책 제목이나 ISBN 입력"><button type="button" class="secondary" id="book-lookup-submit">도서 검색</button></div></div><div id="book-ai-status" role="status" aria-live="polite"></div><div id="book-ai-error" class="error" role="alert"></div><div id="book-ai-candidates"></div><div class="actions"><button type="button" class="secondary" id="retry-book-ai" hidden>다시 시도</button><button type="button" class="quiet" id="manual-book-entry">직접 입력할게요</button></div></section>`;}
export function bibliographicFields(value,esc){
 const info=normalizeInfo(value);
 return `<details class="bibliographic" ${info.isbn||info.publisher||info.category?'open':''}><summary>ISBN·출판사·분류·쪽수 (선택)</summary><div class="two"><div><label for="info-isbn">ISBN</label><input id="info-isbn" name="infoIsbn" maxlength="24" value="${esc(info.isbn)}" placeholder="10자리 또는 13자리"></div><div><label for="info-publisher">출판사</label><input id="info-publisher" name="infoPublisher" maxlength="120" value="${esc(info.publisher)}"></div></div><div class="two"><div><label for="info-category">도서 검색 분류</label><input id="info-category" name="infoCategory" maxlength="200" value="${esc(info.category)}"></div><div><label for="info-pages">쪽수</label><input id="info-pages" name="infoPages" type="number" min="1" max="20000" step="1" value="${info.pageCount||''}" placeholder="정보가 없으면 비워두세요"></div></div><input type="hidden" name="infoSource" value="${esc(info.source)}"><input type="hidden" name="infoSourceId" value="${esc(info.sourceId)}"><input type="hidden" name="aiReviewed" value="1"><div class="notice book-ai-review" hidden><label><input type="checkbox" id="book-ai-reviewed"> 자동 입력한 도서 정보와 직접 선택한 책 상태·교환 조건을 확인했어요.</label><small>확인하거나 수정한 후 체크해주세요. 책 상태와 교환 조건은 아래에서 직접 확인해야 해요.</small></div></details>`;
}
function tags(name,values,selected,esc){return `<input type="hidden" name="${name}" value="${esc(selected.join(','))}"><div class="info-tags">${values.map(value=>`<button type="button" class="chip ${selected.includes(value)?'active':''}" data-info-target="${name}" data-info-value="${esc(value)}" aria-pressed="${selected.includes(value)}">${esc(value)}</button>`).join('')}</div>`;}
export function exchangeInfoFields(value,esc){
 const info=normalizeInfo(value);
 return `<details class="exchange-info"><summary>추천을 위한 분위기·교환 정보 (선택)</summary><p class="hint">등록자가 직접 확인한 정보만 선택해주세요. 비어 있는 정보는 AI가 추측하지 않아요.</p><label for="info-region">교환 지역</label><input id="info-region" name="infoRegion" maxlength="60" value="${esc(info.region)}" placeholder="예: 서울 마포구"><small>다른 이용자에게 공개돼요. 상세 주소·전화번호 대신 시·구·동 정도로 적어주세요.</small><label>책 분위기 · 여러 개 선택</label>${tags('infoMoods',MOODS,info.moods,esc)}<label>가능한 교환 방식</label>${tags('infoMethods',TRADE_METHODS,info.tradeMethods,esc)}<label>교환받고 싶은 책 분야</label>${tags('infoWanted',INFO_GENRES,info.wantedGenres,esc)}<small>이 항목은 사진 자동 입력으로 바뀌지 않아요.</small></details>`;
}
export function detailBookInfo(value,esc){const info=normalizeInfo(value),items=[['ISBN',info.isbn],['출판사',info.publisher],['분류',info.category],['분량',info.pageCount?info.pageCount+'쪽':''],['교환 지역',info.region],['분위기',info.moods.join(' · ')],['교환 방식',info.tradeMethods.join(' · ')],['원하는 책 분야',info.wantedGenres.join(' · ')]];return items.some(([,v])=>v)?`<dl class="book-facts">${items.filter(([,v])=>v).map(([label,v])=>`<div><dt>${label}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`:'';}

export function bindBookAI(form,{request,cover,changed,esc}){
 const el=id=>form.querySelector('#'+id),field=name=>form.elements.namedItem(name);
 let busy=false,candidates=[],selected=-1,lastMode='photo',referenceCover=cover(),cooldown=0,timer;
 const current=()=>form.isConnected;
 const review=()=>{const required=field('aiReviewed').value==='0';el('book-ai-reviewed').checked=!required;el('book-ai-reviewed').required=required;form.querySelector('.book-ai-review').hidden=!required;if(required)form.querySelector('.bibliographic').open=true;};
 const paintTags=()=>form.querySelectorAll('[data-info-target]').forEach(button=>{const values=field(button.dataset.infoTarget).value.split(',');button.classList.toggle('active',values.includes(button.dataset.infoValue));button.setAttribute('aria-pressed',String(values.includes(button.dataset.infoValue)));});
 const ready=()=>{const photo=/^data:image\/(jpeg|png|webp);base64,/.test(cover());el('ai-fill-book').disabled=busy||!photo||!!form.querySelector('button.primary:disabled');el('book-lookup-submit').disabled=busy;el('book-ai-photo-help').textContent=photo?'첨부한 사진으로 조회한 뒤, 같은 도서를 선택해 적용해주세요.':'표지 사진을 먼저 첨부하거나 제목으로 직접 검색해주세요.';};
 const updateCooldown=()=>{const remaining=Math.max(0,Math.ceil((cooldown-Date.now())/1000));el('retry-book-ai').disabled=busy||remaining>0;el('retry-book-ai').textContent=remaining?`${remaining}초 후 재시도`:'다시 시도';if(!current()||!remaining)clearInterval(timer);};
 const renderCandidates=()=>{
  el('book-ai-candidates').innerHTML=candidates.length?`<fieldset><legend>표지와 같은 도서를 선택해주세요</legend><p class="hint">제목·저자·도서 정보·소개가 선택한 도서 정보로 바뀝니다. 책 상태·교환 조건·연락처는 유지돼요.</p>${candidates.map((b,i)=>`<button type="button" class="book-candidate ${selected===i?'selected':''}" data-book-candidate="${i}" aria-pressed="${selected===i}"><strong>${esc(b.title)}</strong><span>${esc(b.author||'저자 정보 없음')} · ${esc(b.metadata.publisher||'출판사 정보 없음')}</span><small>ISBN ${esc(b.metadata.isbn||'정보 없음')} · ${esc(b.metadata.category||'분류 정보 없음')}</small><small>${esc(b.description||'조회된 책 소개가 없어요. 소개는 직접 입력할 수 있어요.')}</small></button>`).join('')}<button type="button" class="secondary" id="apply-book-candidate" ${selected<0?'disabled':''}>선택한 도서 정보로 채우기</button><small>정보 출처: Google Books · 자동 등록되지 않아요.</small></fieldset>`:'';
  form.querySelectorAll('[data-book-candidate]').forEach(button=>button.onclick=()=>{selected=Number(button.dataset.bookCandidate);renderCandidates();});
  if(el('apply-book-candidate'))el('apply-book-candidate').onclick=()=>{
   if(!current())return;if(lastMode==='photo'&&cover()!==referenceCover){el('book-ai-error').textContent='사진이 바뀌었어요. 새 사진으로 다시 조회해주세요.';return;}
   const b=candidates[selected];if(!b)return;
   if([field('title').value,field('author').value,field('description').value].some(v=>v.trim())&&!confirm('입력한 제목·저자·소개와 도서 부가정보를 선택한 도서 정보로 바꿀까요? 책 상태와 교환 조건은 유지돼요.'))return;
   const info=normalizeInfo(b.metadata);
   for(const [name,value] of Object.entries({title:b.title,author:b.author,description:b.description,infoIsbn:info.isbn,infoPublisher:info.publisher,infoCategory:info.category,infoPages:info.pageCount||'',infoSource:info.source,infoSourceId:info.sourceId,aiReviewed:'0'}))field(name).value=value;
   if(b.genre){field('genre').value=b.genre;field('genreDetail').value=info.category.slice(0,40);field('genre').dispatchEvent(new Event('change',{bubbles:true}));}
   form.querySelector('.bibliographic').open=true;review();changed();el('book-ai-status').textContent='도서 정보를 채웠어요. 제목·저자·소개와 ISBN·출판사·분류·쪽수를 확인하고 수정해주세요.';field('title').focus();
  };
 };
 async function run(mode){
  if(busy)return;if(cooldown>Date.now()){el('book-ai-error').textContent='호출 한도가 풀린 뒤 다시 시도해주세요. 직접 입력은 계속 가능해요.';return;}
  const query=el('book-lookup-query').value.trim();if(mode==='photo'&&!/^data:image\//.test(cover()))return;if(mode==='lookup'&&query.length<2){el('book-ai-error').textContent='책 제목이나 ISBN을 두 글자 이상 입력해주세요.';return;}
  busy=true;lastMode=mode;referenceCover=cover();candidates=[];selected=-1;renderCandidates();ready();el('book-ai-error').textContent='';el('retry-book-ai').hidden=true;el('book-ai-status').textContent=mode==='photo'?'표지 글자를 읽고 실제 도서를 찾고 있어요…':'실제 도서 정보를 검색하고 있어요…';
  try{const result=await request(mode==='photo'?{mode,image:referenceCover}:{mode,query});if(!current())return;if(mode==='photo'&&cover()!==referenceCover){el('book-ai-status').textContent='사진이 변경되어 이전 결과는 적용하지 않았어요. 다시 조회해주세요.';return;}candidates=Array.isArray(result.candidates)?result.candidates.slice(0,6):[];if(result.extracted?.title)el('book-lookup-query').value=result.extracted.title;el('book-ai-status').textContent=result.message||'검색이 끝났어요. 도서를 선택하거나 직접 입력해주세요.';renderCandidates();}
  catch(error){if(!current())return;el('book-ai-status').textContent='';el('book-ai-error').textContent=error.message;el('retry-book-ai').hidden=false;if(error.retryAfter){cooldown=Date.now()+error.retryAfter*1000;clearInterval(timer);timer=setInterval(updateCooldown,1000);}}
  finally{busy=false;if(current()){ready();updateCooldown();}}
 }
 el('ai-fill-book').onclick=()=>run('photo');el('book-lookup-submit').onclick=()=>run('lookup');el('retry-book-ai').onclick=()=>run(lastMode);el('book-lookup-query').onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();void run('lookup');}};
 el('manual-book-entry').onclick=()=>{field('title').focus();el('book-ai-status').textContent='아래 항목을 직접 입력하고 등록할 수 있어요.';};
 el('book-ai-reviewed').onchange=event=>{field('aiReviewed').value=event.target.checked?'1':'0';el('book-ai-reviewed').required=!event.target.checked;changed();};
 form.querySelectorAll('[data-info-target]').forEach(button=>button.onclick=()=>{const input=field(button.dataset.infoTarget),values=input.value.split(',').filter(Boolean),value=button.dataset.infoValue;input.value=(values.includes(value)?values.filter(v=>v!==value):[...values,value]).join(',');paintTags();changed();});
 review();paintTags();ready();
 return {refreshCover(){if(cover()!==referenceCover){candidates=[];selected=-1;renderCandidates();if(field('infoSourceId').value){field('aiReviewed').value='0';review();changed();}}ready();},dispose(){clearInterval(timer);}};
}

let chat={owner:null,state:normalizeState(),draft:'',turns:[],results:[],relaxations:[],busy:false,error:'',retry:null,cooldown:0,ticket:0};
export function setAIAccount(owner){if(chat.owner!==owner)chat={owner,state:normalizeState(),draft:'',turns:[],results:[],relaxations:[],busy:false,error:'',retry:null,cooldown:0,ticket:chat.ticket+1};}
export function renderAIChat({esc,card,book,user}){
 if(!user)return `<section class="ai-chat panel"><h2>대화로 교환할 책 찾기</h2><p>로그인하면 원하는 조건을 이야기하며 실제 등록 매물에서 추천받을 수 있어요.</p><a class="secondary" href="#/login">로그인하고 이용하기</a></section>`;
 const results=chat.results.map(result=>{const actual=book(result.id);if(!actual||actual.status!=='available'||!matchesFilters(actual,chat.state.required))return null;const reasons=matchedReasons(actual,chat.state),codes=result.reasonCodes?.filter(c=>Object.hasOwn(reasons,c))||[];return {...actual,reason:(codes.length?codes.map(c=>reasons[c]):[reasons.available]).join(' · ')};}).filter(Boolean);
 const conditionHTML=['required','preferred'].map(priority=>`<div class="chat-condition-group"><b>${priority==='required'?'필수 조건':'선호 조건'}</b>${FILTER_FIELDS.filter(key=>hasFilter(chat.state[priority],key)).map(key=>`<button type="button" class="condition-token ${priority}" data-clear-priority="${priority}" data-clear-condition="${key}" aria-label="${priority==='required'?'필수':'선호'} ${FILTER_LABELS[key]} 조건 삭제">${FILTER_LABELS[key]}: ${esc(filterDescription(chat.state[priority],key))}<span aria-hidden="true"> ×</span></button>`).join('')||'<span class="hint">아직 없어요</span>'}</div>`).join('');
 return `<section class="ai-chat panel" aria-labelledby="ai-chat-heading"><div class="ai-chat-head"><div><span class="eyebrow">REGISTERED BOOKS ONLY</span><h2 id="ai-chat-heading">대화로 교환할 책 찾기</h2></div><button type="button" class="quiet" id="reset-ai-chat" ${chat.busy?'disabled':''}>대화 새로 시작</button></div><p class="hint">원하는 분야·분위기·분량·지역을 알려주세요. 꼭 지켜야 하는 조건은 ‘필수’라고 말씀해주세요. 등록된 정보로 확인할 수 있는 책만 추천해요.</p><div class="chat-turns" aria-live="polite">${chat.turns.length?chat.turns.map(turn=>`<p class="chat-turn ${turn.role}"><b>${turn.role==='user'?'나':'책잇'}</b><span>${esc(turn.text)}</span></p>`).join(''):'<p class="chat-turn assistant"><b>책잇</b><span>어떤 책을 찾으세요? “따뜻한 소설을 읽고 싶어. 300쪽 이하는 필수야”처럼 알려주세요.</span></p>'}</div><div class="chat-conditions">${conditionHTML}</div><form id="ai-chat-form"><label for="ai-chat-message">찾고 싶은 책과 교환 조건</label><textarea id="ai-chat-message" name="message" maxlength="700" rows="3" placeholder="예: 서울 마포구 직거래는 필수, 잔잔한 에세이를 선호해요">${esc(chat.draft)}</textarea><div class="ai-chat-actions"><small>대화·관심 장르·후보 도서의 공개 정보는 AI 서비스로 전송돼요. 연락처·상세 주소는 적지 마세요.</small><button class="primary" ${chat.busy?'disabled':''}>${chat.busy?'조건과 실제 매물 확인 중…':'추천받기'}</button></div></form>${chat.busy?'<p class="notice" role="status">조건을 읽고 교환 가능한 실제 매물을 확인하고 있어요…</p>':''}${chat.error?`<div class="error" role="alert">${esc(chat.error)}</div><button type="button" class="secondary" id="retry-ai-chat" ${chat.busy?'disabled':''}>${chat.cooldown>Date.now()?Math.ceil((chat.cooldown-Date.now())/1000)+'초 후 재시도':'다시 시도'}</button><p class="hint">아래의 기존 맞춤 추천과 직접 검색은 계속 이용할 수 있어요.</p>`:''}${chat.relaxations.length?`<div class="chat-relaxations"><p>필수 조건을 하나만 선호 조건으로 바꿔 다시 찾아볼 수 있어요.</p>${chat.relaxations.map(key=>`<button type="button" class="secondary" data-relax-condition="${key}" ${chat.busy?'disabled':''}>${FILTER_LABELS[key]} 조건 완화</button>`).join('')}</div>`:''}${chat.results.length&&!results.length?'<p class="notice">추천된 책의 상태나 정보가 변경되었어요. 조건으로 다시 찾아주세요.</p>':''}${results.length?`<div class="sectionhead"><h3>대화 조건에 맞는 실제 매물</h3><span class="hint">${results.length}권</span></div><div class="grid chat-results">${results.map(card).join('')}</div>`:''}</section>`;
}
export function bindAIChat({request,paint,adopt,owner}){
 const form=document.querySelector('#ai-chat-form');if(!form)return;
 const log=document.querySelector('.chat-turns');if(log)log.scrollTop=log.scrollHeight;
 const input=form.querySelector('textarea');input.oninput=()=>chat.draft=input.value;
 async function send(payload,retry=false){
  if(chat.busy||chat.owner!==owner)return;if(chat.cooldown>Date.now()){chat.error=`호출 한도가 풀린 뒤 다시 시도해주세요. 약 ${Math.ceil((chat.cooldown-Date.now())/60)}분 남았어요.`;paint();return;}
  if(!payload.message?.trim()&&!payload.relax){chat.error='찾고 싶은 책을 입력해주세요.';paint();return;}
  const ticket=++chat.ticket;chat.busy=true;chat.error='';chat.retry=payload;chat.results=[];chat.relaxations=[];
  if(!retry){chat.turns.push({role:'user',text:payload.relax?`${FILTER_LABELS[payload.relax]} 필수 조건을 선호로 바꿔줘`:payload.message});chat.draft='';}chat.turns=chat.turns.slice(-20);paint();
  try{const result=await request({mode:'chat',message:payload.message||'',state:chat.state,...(payload.relax?{relax:payload.relax}:{})});if(chat.owner!==owner||chat.ticket!==ticket)return;chat.state=normalizeState(result.state);chat.results=Array.isArray(result.books)?result.books:[];adopt(chat.results);chat.relaxations=Array.isArray(result.relaxations)?result.relaxations.filter(k=>FILTER_FIELDS.includes(k)):[];chat.turns.push({role:'assistant',text:result.question||result.message||'다시 원하는 조건을 알려주세요.'});chat.retry=null;}
  catch(error){if(chat.owner!==owner||chat.ticket!==ticket)return;chat.error=error.message;if(error.retryAfter)chat.cooldown=Date.now()+error.retryAfter*1000;}
  finally{if(chat.owner===owner&&chat.ticket===ticket){chat.busy=false;paint();}}
 }
 form.onsubmit=event=>{event.preventDefault();void send({message:input.value.trim()});};
 if(document.querySelector('#retry-ai-chat'))document.querySelector('#retry-ai-chat').onclick=()=>{if(chat.retry)void send(chat.retry,true);};
 document.querySelectorAll('[data-relax-condition]').forEach(button=>button.onclick=()=>send({message:'',relax:button.dataset.relaxCondition}));
 document.querySelectorAll('[data-clear-condition]').forEach(button=>button.onclick=()=>{if(chat.busy)return;chat.state[button.dataset.clearPriority][button.dataset.clearCondition]=normalizeFilter()[button.dataset.clearCondition];chat.state.dismissed=[...new Set([...chat.state.dismissed,button.dataset.clearCondition])];chat.results=[];chat.relaxations=[];paint();});
 if(document.querySelector('#reset-ai-chat'))document.querySelector('#reset-ai-chat').onclick=()=>{if(chat.busy)return;setAIAccount(null);setAIAccount(owner);paint();};
}
